  const starts = [0.35, 0.33, 0.25, 0.16, 0.09, 0.07, 0.0];
  lettersG.setAttribute('transform', `translate(${x0} ${y0}) scale(${k})`);
  IV_SHAPES.L.forEach((Sh, j) => {
    const q = clamp((p - starts[j]) / 0.35);
    if (q >= 1) { letterPaths[j].setAttribute('d', ''); return; }
    const travel = Math.pow(q, 2.2), mx = Sh.cx + (tx - Sh.cx) * travel, my = Sh.cy + (ty - Sh.cy) * travel;
    const sc = 1 - Math.pow(q, 1.5), m = clamp(q * 1.7), rad = Math.sqrt(Sh.w * Sh.h) * 0.42;
    const sx = 1 + 0.9 * Math.sin(Math.PI * q), sy = 1 - 0.35 * Math.sin(Math.PI * q);
    const A = Sh.A, B = Sh.B; let d = '';
