      const ox = (A[i] - Sh.cx) * (1 - m) + B[i] * rad * m, oy = (A[i + 1] - Sh.cy) * (1 - m) + B[i + 1] * rad * m;
      d += (i ? 'L' : 'M') + (mx + ox * sc * sx).toFixed(1) + ',' + (my + oy * sc * sy).toFixed(1);
    }
