    const ang = Math.atan2(C[i + 1] - 185.35, C[i] - 563);
    const wob = env * (0.09 * Math.sin(3 * ang + 11 * p) + 0.05 * Math.sin(5 * ang - 17 * p) + 0.03 * Math.sin(8 * ang + 23 * p));
