/* ---------- date / cypher ---------- */
const dateEl = $('#date');
function setDate(text) {
  const old = dateEl.dataset.v || '';
  if (old === text) return;
  dateEl.dataset.v = text;
  dateEl.setAttribute('aria-label', text);
  const plain = () => { dateEl.innerHTML = [...text].map((c) => `<span class="dg"><span class="col"><span>${c}</span></span></span>`).join(''); };
  if (reduce || !old || old.length !== text.length || /\D/.test(old + text)) { plain(); return; }
  dateEl.innerHTML = '';
  [...text].forEach((c, n) => {
    const a = +old[n], b = +c, seq = [a];
    if (a !== b) { let d = a; do { d = (d + 1) % 10; seq.push(d); } while (d !== b); }
    const dg = document.createElement('span'); dg.className = 'dg';
    const col = document.createElement('span'); col.className = 'col';
    col.innerHTML = seq.map((d) => `<span>${d}</span>`).join('');
    dg.appendChild(col); dateEl.appendChild(dg);
    if (seq.length > 1) {
      const steps = seq.length - 1;
      col.animate([{ transform: 'translateY(0)' }, { transform: `translateY(-${steps * 1.25}em)` }],
        { duration: 520 + steps * 28, delay: n * 55, easing: 'cubic-bezier(.32,.72,0,1)', fill: 'forwards' });
    }
  });
}
const catEl = $('#cat');
function setCat(text) {
  if (catEl.textContent === text) return;
  if (reduce || !catEl.textContent) { catEl.textContent = text; return; }
