function flight(fromRect, toEl, src, fit, bg, radiusFrom, radiusTo, done) {
  const to = toEl.getBoundingClientRect();
  const fly = document.createElement('div');
  fly.className = 'fly';
  fly.style.cssText = `left:${to.left}px;top:${to.top}px;width:${to.width}px;height:${to.height}px;background:${bg};border-radius:${radiusTo}px`;
  fly.innerHTML = `<img class="media${fit === 'contain' ? ' contain' : ''}" src="${src}" alt="">`;
  document.body.appendChild(fly);
  const sx = fromRect.width / to.width, sy = fromRect.height / to.height;
  const a = fly.animate([
    { transform: `translate(${fromRect.left - to.left}px, ${fromRect.top - to.top}px) scale(${sx}, ${sy})`, borderRadius: `${radiusFrom / sx}px` },
    { transform: 'none', borderRadius: `${radiusTo}px` }
  ], { duration: 620, easing: 'cubic-bezier(.32,.72,0,1)', fill: 'both' });
  a.onfinish = () => { done && done(); requestAnimationFrame(() => fly.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 160, fill: 'both' }).onfinish = () => fly.remove()); };
}
function radiusOf(el) { return parseFloat(getComputedStyle(el).borderTopLeftRadius) || 18; }

