/* shape: the cart bar never moves. The title bar's end pulls away from it (split) or reaches back to it (merge);
   between them a neck joins two round ends, thins, and snaps or fuses (after iOS liquid glass) */
function bar1Path(W, h, st) {
  const r = h / 2, f = (n) => n.toFixed(2);
