  if (neck > 0) {
    const w = r * neck, phi = (1 - neck) * 1.15, sn = Math.sin(phi), cs = Math.cos(phi);
    const p1x = eA - r + r * sn, p1y = r - r * cs, p2x = eB + r - r * sn;
    const tl = Math.max(2, (p2x - p1x) * 0.32), hx = Math.max(1, (c - p1x) * 0.55);
    return `${capA} A ${f(r)} ${f(r)} 0 0 1 ${f(p1x)} ${f(p1y)} C ${f(p1x + tl * cs)} ${f(p1y + tl * sn)} ${f(c - hx)} ${f(r - w)} ${f(c)} ${f(r - w)} C ${f(c + hx)} ${f(r - w)} ${f(p2x - tl * cs)} ${f(p1y + tl * sn)} ${f(p2x)} ${f(p1y)} A ${f(r)} ${f(r)} 0 0 1 ${f(eB + r)} 0 `
      + `${endB} A ${f(r)} ${f(r)} 0 0 1 ${f(p2x)} ${f(h - p1y)} C ${f(p2x - tl * cs)} ${f(h - p1y - tl * sn)} ${f(c + hx)} ${f(r + w)} ${f(c)} ${f(r + w)} C ${f(c - hx)} ${f(r + w)} ${f(p1x + tl * cs)} ${f(h - p1y - tl * sn)} ${f(p1x)} ${f(h - p1y)} A ${f(r)} ${f(r)} 0 0 1 ${f(eA - r)} ${f(h)} H ${f(r)} A ${f(r)} ${f(r)} 0 0 1 ${f(r)} 0 Z`;
  }
  return `${capA} A ${f(r)} ${f(r)} 0 0 1 ${f(eA - r)} ${f(h)} H ${f(r)} A ${f(r)} ${f(r)} 0 0 1 ${f(r)} 0 Z M ${f(eB + r)} 0 ${endB} A ${f(r)} ${f(r)} 0 0 1 ${f(eB + r)} 0 Z`;
}
function drawSplit(st) {
  Object.assign(splitState, st);
  const rc = bar1.getBoundingClientRect();
  const d = bar1Path(rc.width, rc.height, st);
